import { PASSWORD, USERS, expect, test } from "../../fixtures";

test("signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ request }) => {
  // Arrange: sign in so the session cookie is stored in this request context
  const login = await request.post("/api/auth/login", {
    data: { email: USERS.member, password: PASSWORD },
  });
  expect(login.status(), await login.text()).toBe(200);

  // Act
  const response = await request.post("/api/auth/logout");

  // Assert
  expect(response.status(), await response.text()).toBe(204);
  const setCookies = response
    .headersArray()
    .filter((h) => h.name.toLowerCase() === "set-cookie")
    .map((h) => h.value);
  const sessionCookie = setCookies.find((v) => v.toLowerCase().startsWith("session="));
  expect(sessionCookie, `Set-Cookie headers: ${setCookies.join(" | ")}`).toBeDefined();
  const lower = sessionCookie!.toLowerCase();
  const cleared =
    lower.includes("max-age=0") ||
    lower.includes("expires=thu, 01 jan 1970") ||
    lower.startsWith("session=;") ||
    lower.startsWith("session=\"\";");
  expect(cleared, `session cookie not cleared: ${sessionCookie}`).toBe(true);
});
